parameters.jsCode:
const item = $json;

// -------------------------
// AI SIGNAL SCORE TABLES
// -------------------------

const purchaseIntentScores = {
  high: 15,
  medium: 8,
  low: 2,
  unknown: 0,
};

const businessImpactScores = {
  high: 10,
  medium: 5,
  low: 1,
  unknown: 0,
};

const specificityScores = {
  high: 5,
  medium: 3,
  low: 0,
};

const urgencySignalScores = {
  emergency: 10,
  same_day: 6,
  within_48h: 3,
  quote_only: 0,
  unknown: 0,
};

// -------------------------
// CALCULATE AI SCORE
// -------------------------

const purchaseIntentScore =
  purchaseIntentScores[item.purchaseIntent] ?? 0;

const businessImpactScore =
  businessImpactScores[item.businessImpact] ?? 0;

const specificityScore =
  specificityScores[item.specificity] ?? 0;

const messageUrgencyScore =
  urgencySignalScores[item.messageUrgencySignal] ?? 0;

const aiScore =
  purchaseIntentScore +
  businessImpactScore +
  specificityScore +
  messageUrgencyScore;

// -------------------------
// RULE SCORE
// -------------------------

const ruleScore = Number(item.ruleScore ?? 0);

// -------------------------
// HYBRID SCORE
// -------------------------

const hybridScore = ruleScore + aiScore;

// -------------------------
// OUTPUT
// -------------------------

return {
  json: {
    ...item,

    ruleScore,

    aiScore,

    aiScoreBreakdown: {
      purchaseIntent: purchaseIntentScore,
      businessImpact: businessImpactScore,
      specificity: specificityScore,
      messageUrgencySignal: messageUrgencyScore,
    },

    hybridScore,
  },
};

const urgencyRank = {
  quote_only: 1,
  within_48h: 2,
  same_day: 3,
  emergency: 4,
  unknown: 0,
};

const formUrgency = $json.urgency;
const aiUrgency = $json.messageUrgencySignal;

const formUrgencyRank = urgencyRank[formUrgency] ?? 0;
const aiUrgencyRank = urgencyRank[aiUrgency] ?? 0;

const effectiveUrgency =
  aiUrgencyRank > formUrgencyRank
    ? aiUrgency
    : formUrgency;

return {
  ...$json,
  effectiveUrgency,
};
